Add CLI and MCP capabilities for also storing additional relevant entities, inspired by the outcome-driven innovation framework. Here is an example: "In Outcome-Driven Innovation (ODI), a fundamental principle is the dual-value loop:Customer Desired Outcomes define the value created for the customer (solving their friction in executing a job).Business Outcomes (or Capture) define the economic value returned to the business as a result of satisfying those customer outcomes.ODI typically connects customer outcomes to business outcomes through value drivers like market opportunity size, willingness to pay, reduced support costs, customer retention, or expansion potential.To encapsulate this in a data structure, we extend the outcome entity to map the Customer Desired Outcome directly to its expected Business Value Capture.Extended Data Schema (TypeScript)TypeScripttype Direction = 'minimize' | 'maximize';
type BusinessImpactCategory = 
  | 'revenue_growth' 
  | 'cost_reduction' 
  | 'retention' 
  | 'risk_mitigation';

interface CustomerOutcome {
  id: string;                      // e.g., "OUT-101"
  jobStepId: string;

  // 1. Customer-Facing Desired Outcome (ODI Core)
  customerValue: {
    statement: {
      direction: Direction;
      unitOfMeasure: string;
      objectOfControl: string;
      contextualClarifier: string;
      fullText: string;
    };
    metrics: {
      importanceScore: number;     // 1-10
      satisfactionScore: number;   // 1-10
      opportunityScore: number;    // Computed ODI score
    };
    opportunityType: 'underserved' | 'appropriately_served' | 'overserved';
  };

  // 2. Business Value Capture (Reaped Value)
  businessValue: {
    impactCategory: BusinessImpactCategory;
    hypothesis: string;             // How solving the customer outcome yields business value
    kpis: {
      metricName: string;          // e.g., "Customer Churn Rate", "Support Ticket Volume"
      currentValue: number;
      targetValue: number;
      unit: string;                // e.g., "%", "USD", "hours"
    }[];
    estimatedFinancialImpact: {
      value: number;               // Projected annual financial impact
      currency: string;            // e.g., "USD", "EUR"
      confidence: 'low' | 'medium' | 'high';
    };
    strategicAlignment: string;    // Alignment with broader business goals/OKRs
  };

  metadata?: {
    createdAt: string;
    updatedAt: string;
    targetSegment?: string;
  };
}
